
import jsPDF from "jspdf";
import html2canvas from "html2canvas";
import React, { useState, useEffect } from "react";
import { Bar, Pie, Line } from "react-chartjs-2";
import { BarChart2, FileText, Settings, Sun, Moon } from "lucide-react";
import "./App.css";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  ArcElement,
  LineElement,
  PointElement,
  Title,
  Tooltip,
  Legend
} from 'chart.js';

// Đăng ký các element và scale
ChartJS.register(
  CategoryScale,
  LinearScale,
  BarElement,
  ArcElement,
  LineElement,
  PointElement,
  Title,
  Tooltip,
  Legend
);

function App() {
  const [activeTab, setActiveTab] = useState("Thống kê");
  const [darkMode, setDarkMode] = useState(false);

  const [incomeData, setIncomeData] = useState(() => JSON.parse(localStorage.getItem("incomeData")) || {});
  const [expensesData, setExpensesData] = useState(() => JSON.parse(localStorage.getItem("expensesData")) || {});
  const [budgets, setBudgets] = useState(() => JSON.parse(localStorage.getItem("budgets")) || {});

  const [chatHistory, setChatHistory] = useState(() => JSON.parse(localStorage.getItem("chatHistory")) || []);
  const [userInput, setUserInput] = useState("");
  const [isChatVisible, setIsChatVisible] = useState(true);
  const [chatPosition, setChatPosition] = useState(() => JSON.parse(localStorage.getItem("chatPosition")) || { bottom: "20px", right: "20px" });

  const today = new Date().toISOString().split("T")[0];
  const currentMonth = today.slice(0, 7);
  const [selectedMonth, setSelectedMonth] = useState(currentMonth);
  const [newCategory, setNewCategory] = useState("");
  const [newAmount, setNewAmount] = useState("");
  const [newDate, setNewDate] = useState(today);
  const [newNote, setNewNote] = useState("");
  const [editIndex, setEditIndex] = useState(null);
  const [filterText, setFilterText] = useState("");
  const [sortOrder, setSortOrder] = useState("desc");

  const categories = ["Ăn uống", "Đi lại", "Giải trí", "Học tập", "Khác"];

  // Sync localStorage
  useEffect(() => { localStorage.setItem("incomeData", JSON.stringify(incomeData)); }, [incomeData]);
  useEffect(() => { localStorage.setItem("expensesData", JSON.stringify(expensesData)); }, [expensesData]);
  useEffect(() => { localStorage.setItem("budgets", JSON.stringify(budgets)); }, [budgets]);
  useEffect(() => { localStorage.setItem("chatHistory", JSON.stringify(chatHistory)); }, [chatHistory]);
  useEffect(() => { localStorage.setItem("chatPosition", JSON.stringify(chatPosition)); }, [chatPosition]);

  const income = incomeData[selectedMonth] || 0;
  const expenses = expensesData[selectedMonth] || [];
  const totalExpense = expenses.reduce((acc, e) => acc + e.amount, 0);
  const highestExpense = expenses.length ? expenses.reduce((a,b)=>a.amount>b.amount?a:b) : null;

  const filteredExpenses = expenses
    .filter(e => e.category.toLowerCase().includes(filterText.toLowerCase()))
    .sort((a,b)=> sortOrder==="desc"?b.amount-a.amount:a.amount-b.amount);

  // Chart data
  const barData = {
    labels: filteredExpenses.map(e=>e.category),
    datasets:[{
      label:"Chi tiêu",
      data:filteredExpenses.map(e=>e.amount),
      backgroundColor: filteredExpenses.map(e=>highestExpense && e.category===highestExpense.category ? "#e74c3c" : "#3498db")
    }]
  };
  const pieData = {
    labels: filteredExpenses.map(e=>e.category),
    datasets:[{ data:filteredExpenses.map(e=>e.amount), backgroundColor:["#ff7675","#74b9ff","#ffeaa7","#55efc4","#a29bfe","#fd79a8"] }]
  };
  const lineData = {
    labels: Object.keys(incomeData).sort(),
    datasets:[
      { label:"Thu nhập", data:Object.keys(incomeData).sort().map(m=>incomeData[m]), borderColor:"#2ecc71", fill:false },
      { label:"Chi tiêu", data:Object.keys(expensesData).sort().map(m=>(expensesData[m]||[]).reduce((a,e)=>a+e.amount,0)), borderColor:"#e74c3c", fill:false }
    ]
  };

  // --- Expense functions ---
  const handleAddExpense = () => {
    if(!newCategory || !newAmount || Number(newAmount)<=0) return;
    const newExpense = {category:newCategory, amount:Number(newAmount), date:newDate, note:newNote};
    const updatedExpenses = [...expenses,newExpense];
    setExpensesData({...expensesData,[selectedMonth]:updatedExpenses});
    setNewCategory(""); setNewAmount(""); setNewDate(today); setNewNote("");
    if(budgets[newCategory] && updatedExpenses.filter(e=>e.category===newCategory).reduce((a,e)=>a+e.amount,0) > budgets[newCategory]){
      alert(`Bạn đã vượt ngân sách của danh mục ${newCategory}!`);
    }
  };
  const handleDeleteExpense = (index) => {
    if(window.confirm("Bạn có chắc muốn xoá khoản chi tiêu này?")){
      const updated = expenses.filter((_,i)=>i!==index);
      setExpensesData({...expensesData,[selectedMonth]:updated});
    }
  };
  const handleSaveEdit = (index)=>{
    if(!newCategory || !newAmount || Number(newAmount)<=0) return;
    const updated = [...expenses];
    updated[index] = {category:newCategory, amount:Number(newAmount), date:newDate, note:newNote};
    setExpensesData({...expensesData,[selectedMonth]:updated});
    setEditIndex(null); setNewCategory(""); setNewAmount(""); setNewDate(today); setNewNote("");
  };

  // --- Chat AI ---
  const handleSend = () => {
    if(!userInput) return;
    setChatHistory([...chatHistory, {user:true,text:userInput}]);
    const text = userInput.toLowerCase();
    let botReply = "Mình chưa hiểu, bạn thử hỏi khác nhé.";
    const moneyLeft = income - totalExpense;
    const predictedExpense = totalExpense * 1.1;

    if(text.includes("tiết kiệm")) botReply = moneyLeft>0?`Bạn có thể để dành ${moneyLeft} VND trong tháng này.`:"Chi tiêu vượt thu nhập.";
    else if(text.includes("dự báo")) botReply = predictedExpense>income?"Chi tiêu sẽ vượt thu nhập nếu tiếp tục như hiện tại.":"Chi tiêu vẫn trong mức an toàn.";
    else if(text.includes("đầu tư")) botReply = moneyLeft>0?"Có thể đầu tư 50% số dư tiết kiệm vào quỹ an toàn.":"Hiện tại không có dư để đầu tư.";
    else if(text.includes("chi tiêu")) botReply = filteredExpenses.length?`Danh mục chi tiêu lớn nhất: ${highestExpense.category} (${highestExpense.amount} VND)`:"Chưa nhập chi tiêu nào.";
    else if(text.includes("chi lớn")){
      const bigExpenses = filteredExpenses.filter(e=>e.amount>income*0.2);
      botReply = bigExpenses.length?`Các khoản chi lớn: ${bigExpenses.map(e=>`${e.category} (${e.amount} VND)`).join(", ")}`:"Hiện chưa có khoản chi lớn.";
    } else if(text.includes("gợi ý")){
      const suggestedSavings = Math.max(Math.round(income*0.2),0);
      botReply = `Bạn nên để dành ít nhất 20% thu nhập (${suggestedSavings} VND) nếu có thể.`;
    }

    setChatHistory(prev=>[...prev,{user:false,text:botReply}]);
    setUserInput("");
  };

  // --- Export ---
  const exportPDF = async () => {
    const input = document.getElementById("report-section");
    const canvas = await html2canvas(input);
    const imgData = canvas.toDataURL("image/png");
    const doc = new jsPDF();
    doc.text(`BÁO CÁO THÁNG ${selectedMonth}`,20,20);
    doc.addImage(imgData,"PNG",15,40,180,100);
    doc.save(`bao_cao_${selectedMonth}.pdf`);
  };
  const exportCSV = () => {
    const rows=[["Danh mục","Số tiền","Ngày","Ghi chú"]];
    expenses.forEach(e=>rows.push([e.category,e.amount,e.date,e.note]));
    const csvContent = "data:text/csv;charset=utf-8," + rows.map(e=>e.join(",")).join("\n");
    const link=document.createElement("a");
    link.setAttribute("href", encodeURI(csvContent));
    link.setAttribute("download", `chi_tieu_${selectedMonth}.csv`);
    document.body.appendChild(link); link.click(); document.body.removeChild(link);
  };

  // --- Render Content ---
  const renderContent = () => {
    switch(activeTab){
      case "Thống kê": return (
        <div className="fadeIn">
          {/* Stats, Add expense */}
          <div className="card">
            <h2>Thống kê tài chính</h2>
            <button onClick={()=>setDarkMode(prev=>!prev)}>{darkMode?<Sun size={18}/>:<Moon size={18}/>} {darkMode?"Light mode":"Dark mode"}</button>
            <h3>Thu nhập: {income} VND</h3>
            <button onClick={()=>{
              const value=Number(prompt("Nhập thu nhập tháng này:"));
              if(value>=0) setIncomeData({...incomeData,[selectedMonth]:value});
            }}>Cập nhật thu nhập</button>

            <div style={{margin:"10px 0"}}>
              <label>Chọn tháng: </label>
              <input type="month" value={selectedMonth} onChange={e=>setSelectedMonth(e.target.value)} />
            </div>

            <h3>Tổng chi tiêu: {totalExpense} VND</h3>
            <h4>Tỷ lệ tiết kiệm: {income?Math.round((income-totalExpense)/income*100):0}%</h4>
          </div>

          <div className="card">
            <h4>Thêm chi tiêu</h4>
            <div style={{display:"flex", gap:"10px", flexWrap:"wrap"}}>
              <select value={newCategory} onChange={e=>setNewCategory(e.target.value)}>
                <option value="">Chọn danh mục</option>
                {categories.map(c=><option key={c} value={c}>{c}</option>)}
              </select>
              <input type="number" placeholder="Số tiền" value={newAmount} onChange={e=>setNewAmount(e.target.value)} />
              <input type="date" value={newDate} onChange={e=>setNewDate(e.target.value)} />
              <input type="text" placeholder="Ghi chú" value={newNote} onChange={e=>setNewNote(e.target.value)} />
              <button onClick={handleAddExpense}>Thêm</button>
            </div>

            <div style={{display:"flex", gap:"10px", margin:"10px 0"}}>
              <input placeholder="Tìm danh mục..." value={filterText} onChange={e=>setFilterText(e.target.value)} />
              <button onClick={()=>setSortOrder(prev=>prev==="desc"?"asc":"desc")}>Sắp xếp: {sortOrder==="desc"?"⬇️":"⬆️"}</button>
            </div>

            <ul style={{listStyle:"none", padding:0}}>
              {filteredExpenses.map((e,idx)=>(
                <li key={idx} className="expense-item">
                  {editIndex===idx ? (
                    <>
                      <select value={newCategory} onChange={ev=>setNewCategory(ev.target.value)}>
                        {categories.map(c=><option key={c} value={c}>{c}</option>)}
                      </select>
                      <input type="number" value={newAmount} onChange={ev=>setNewAmount(ev.target.value)} />
                      <input type="text" value={newNote} placeholder="Ghi chú" onChange={ev=>setNewNote(ev.target.value)} />
                      <button onClick={()=>handleSaveEdit(idx)}>Lưu</button>
                      <button onClick={()=>setEditIndex(null)}>Hủy</button>
                    </>
                  ) : (
                    <>
                      <span>{e.category}: {e.amount} VND — <i>{e.date}</i> — {e.note}</span>
                      <div style={{display:"flex", gap:"5px"}}>
                        <button onClick={()=>{setEditIndex(idx); setNewCategory(e.category); setNewAmount(e.amount); setNewNote(e.note);}}>✏️</button>
                        <button onClick={()=>handleDeleteExpense(idx)}>❌</button>
                      </div>
                    </>
                  )}
                </li>
              ))}
            </ul>
          </div>

          <div style={{display:"flex", flexWrap:"wrap", gap:"20px"}}>
            <div className="card" style={{flex:"1 1 400px"}}><h4>Biểu đồ cột</h4><Bar data={barData} /></div>
            <div className="card" style={{flex:"1 1 300px"}}><h4>Biểu đồ tròn</h4><Pie data={pieData} /></div>
            <div className="card" style={{flex:"1 1 500px"}}><h4>Lịch sử thu/chi</h4><Line data={lineData} /></div>
          </div>
        </div>
      );

      case "Báo cáo": return (
        <div id="report-section" className="fadeIn card">
          <h2>Báo cáo tháng {selectedMonth}</h2>
          <p>Thu nhập: <b>{income} VND</b></p>
          <p>Chi tiêu: <b>{totalExpense} VND</b></p>
          <p>Số dư: <b>{income-totalExpense} VND</b></p>
          <h4>Tỷ lệ tiết kiệm: {income?Math.round((income-totalExpense)/income*100):0}%</h4>
          <button onClick={exportPDF}>📄 Xuất PDF</button>
          <button onClick={exportCSV} style={{marginLeft:"10px"}}>📊 Xuất CSV</button>
        </div>
      );

      case "Cài đặt": return (
        <div className="fadeIn card">
          <h2>Cài đặt</h2>
          <h4>Ngân sách danh mục</h4>
          {categories.map(c=>(
            <div key={c} style={{marginBottom:"8px"}}>
              <label>{c}: </label>
              <input type="number" value={budgets[c]||""} placeholder="Nhập ngân sách" onChange={e=>setBudgets({...budgets,[c]:Number(e.target.value)})} />
            </div>
          ))}
          <button onClick={()=>{if(window.confirm("Bạn có chắc muốn xoá toàn bộ dữ liệu?")){ setIncomeData({}); setExpensesData({}); setBudgets({}); localStorage.clear(); }}}>🚨 Xoá tất cả dữ liệu</button>
        </div>
      );

      default: return null;
    }
  };

  return (
    <div className={`App ${darkMode?"dark-mode":""}`} style={{display:"flex", minHeight:"100vh", fontFamily:"sans-serif"}}>
      {/* Sidebar */}
      <div style={{width:"220px", background:"#2c3e50", color:"#fff", padding:"20px", display:"flex", flexDirection:"column", gap:"15px"}}>
        <h2 style={{marginBottom:"30px"}}>Danh mục</h2>
        {[{label:"Thống kê", icon:<BarChart2 size={18}/>},{label:"Báo cáo", icon:<FileText size={18}/>},{label:"Cài đặt", icon:<Settings size={18}/> }].map(tab=>(
          <button key={tab.label} className={`sidebar-btn ${activeTab===tab.label?"active":""}`} onClick={()=>setActiveTab(tab.label)}>{tab.icon} {tab.label}</button>
        ))}
      </div>

      {/* Main Content */}
      <div style={{flex:1, padding:"30px"}}>
        {renderContent()}
      </div>

      {/* Chat Bot */}
      {isChatVisible && (
        <div
          id="chat-bot"
          style={{
            position: "fixed",
            left: chatPosition.left || "auto",
            top: chatPosition.top || "auto",
            bottom: chatPosition.bottom || "20px",
            right: chatPosition.right || "20px",
            width: "300px",
            background: darkMode ? "#333" : "#f1f1f1",
            color: darkMode ? "#fff" : "#000",
            padding: "10px",
            borderRadius: "12px",
            boxShadow: "0 4px 10px rgba(0,0,0,0.2)",
            display: "flex",
            flexDirection: "column",
            cursor: "move",
            zIndex: 9999
          }}
          onMouseDown={(e)=>{
            const chat = e.currentTarget;
            const offsetX = e.clientX - chat.getBoundingClientRect().left;
            const offsetY = e.clientY - chat.getBoundingClientRect().top;

            const onMouseMove = (eMove)=>{
              chat.style.left = eMove.clientX - offsetX + "px";
              chat.style.top = eMove.clientY - offsetY + "px";
              chat.style.bottom = "auto";
              chat.style.right = "auto";
            };

            const onMouseUp = ()=>{
              setChatPosition({ left: chat.style.left, top: chat.style.top });
              window.removeEventListener("mousemove", onMouseMove);
              window.removeEventListener("mouseup", onMouseUp);
            };

            window.addEventListener("mousemove", onMouseMove);
            window.addEventListener("mouseup", onMouseUp);
          }}
        >
          {/* Header */}
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "8px" }}>
            <b>Chat Bot</b>
            <button onClick={()=>setIsChatVisible(false)} style={{ background: "transparent", border: "none", color: darkMode ? "#fff" : "#000", cursor: "pointer", fontSize: "16px" }}>✖</button>
          </div>

          {/* Chat content */}
          <div style={{ maxHeight: "200px", overflowY: "auto", display: "flex", flexDirection: "column", marginBottom: "10px" }}>
            {chatHistory.map((msg, idx)=>(
              <div key={idx} className={`chat-bubble ${msg.user ? "user-bubble" : "bot-bubble"}`}>{msg.text}</div>
            ))}
          </div>

          {/* Input */}
          <div style={{ display: "flex", gap:"5px" }}>
            <input style={{flex:1}} value={userInput} onChange={e=>setUserInput(e.target.value)} placeholder="Hỏi trợ lý tài chính..." />
            <button onClick={handleSend}>Gửi</button>
          </div>
        </div>
      )}

      {/* Open Chat Button */}
      {!isChatVisible && (
        <button onClick={()=>setIsChatVisible(true)} style={{ position:"fixed", bottom:"20px", right:"20px", zIndex:9999, background:"#1abc9c", color:"#fff", borderRadius:"50%", width:"50px", height:"50px", border:"none", cursor:"pointer", boxShadow:"0 4px 10px rgba(0,0,0,0.2)" }}>💬</button>
      )}
    </div>
  );
}

export default App;
